create table if not exists public.enquiries(id bigint generated by default as identity primary key,name text not null check(char_length(name) between 1 and 100),phone text not null check(char_length(phone) between 1 and 25),service text not null check(char_length(service) between 1 and 100),message text not null default '' check(char_length(message)<=1500),created_at timestamptz not null default now());
alter table public.enquiries enable row level security;
create policy "Anyone can submit an enquiry" on public.enquiries for insert to anon,authenticated with check(char_length(trim(name)) between 1 and 100 and char_length(trim(phone)) between 1 and 25 and char_length(trim(service)) between 1 and 100 and char_length(coalesce(message,''))<=1500);
-- Secure by default: do not add a SELECT policy until your admin UUID is known.
-- create policy "Only shop admin can read enquiries" on public.enquiries for select to authenticated using(auth.uid()='YOUR_ADMIN_USER_UUID'::uuid);
-- Never expose the Supabase service_role key in frontend code.